<script setup lang="ts">definePageMeta({layout:'admin'});const {data,pending,error,refresh}=await useFetch('/api/admin/dashboard',{transform:(r:any)=>r.data});const fmt=(d:string)=>new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(new Date(d))</script><template><div class="admin-page"><AdminPageHeader title="Dashboard" description="Ringkasan katalog dan inventaris terkini."/><div v-if="pending">Memuat ringkasan…</div><button v-else-if="error" class="btn btn-outline" @click="refresh()">Coba muat lagi</button><template v-else><div class="metrics"><MetricCard label="Produk aktif" :value="data.metrics.activeProducts"/><MetricCard label="Total unit stok" :value="data.metrics.totalUnits"/><MetricCard label="Stok menipis" :value="data.metrics.lowStockProducts"/><MetricCard label="Klik WhatsApp bulan ini" :value="data.metrics.whatsappClicksThisMonth"/></div><div class="quick"><NuxtLink class="btn btn-primary" to="/admin/produk/tambah">Tambah Produk</NuxtLink><NuxtLink class="btn btn-outline" to="/admin/stok/masuk">Barang Masuk</NuxtLink><NuxtLink class="btn btn-outline" to="/admin/stok/keluar">Barang Keluar</NuxtLink><NuxtLink class="btn btn-outline" to="/admin/laporan">Lihat Laporan</NuxtLink></div><div class="columns"><section class="panel box"><h2>Stok menipis</h2><div v-if="!data.lowStock.length" class="muted">Semua stok dalam kondisi aman.</div><div v-for="x in data.lowStock" :key="x.id" class="row"><span><b>{{x.name}}</b><small>{{x.sku}}</small></span><ProductStockBadge :stock="x.stock" :threshold="x.threshold"/></div></section><section class="panel box"><h2>Aktivitas stok terbaru</h2><div v-if="!data.recentMovements.length" class="muted">Belum ada pergerakan stok.</div><div v-for="x in data.recentMovements" :key="x.id" class="row"><span><b>{{x.productName}}</b><small>{{fmt(x.movement_at)}} · {{x.adminName}}</small></span><b>{{x.movement_type}} {{x.quantity}}</b></div></section></div></template></div></template><style scoped>.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem}.quick{display:flex;gap:.6rem;flex-wrap:wrap}.columns{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.box{padding:1.2rem}.box h2{font-size:1rem;margin:0 0 1rem}.row{display:flex;align-items:center;justify-content:space-between;padding:.75rem 0;border-bottom:1px solid var(--border);font-size:.82rem}.row:last-child{border:0}.row span small{display:block;color:var(--muted);margin-top:.2rem}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.columns{grid-template-columns:1fr}}@media(max-width:450px){.metrics{grid-template-columns:1fr}}</style>
